public class Main {
    public static void main(String[] args) {
        System.out.println(2 + 3 * 4);      // the multiply goes first
        System.out.println((2 + 3) * 4);    // brackets go first
        System.out.println(20 - 6 / 2);     // the divide goes first
        System.out.println(10 - 4 - 3);     // equal rank: left to right
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Bill total? ");
        double total = scanner.nextDouble();

        System.out.print("How many people? ");
        int people = scanner.nextInt();

        double each = total / people;

        System.out.println("Each person pays " + each);
    }
}

